export function getCategoryForDrug(drug: DrugMonograph): string {
  const name = drug.drug_class_name || drug.drug_class || '';
  if (name.includes('Anti-infectives')) return 'Anti-infectives';
  if (name.includes('Cardiovascular')) return 'Cardiovascular';
  if (name.includes('Central Nervous System')) return 'Central Nervous System';
  if (name.startsWith('Analgesics')) return 'Analgesics';
  if (name.startsWith('Gastrointestinal')) return 'Gastrointestinal';
  if (name.startsWith('Endocrine')) return 'Endocrine';
  if (name.startsWith('Respiratory')) return 'Respiratory';
  if (name.startsWith('Anticoagulants')) return 'Anticoagulants';
  if (name.startsWith('Oncology')) return 'Oncology';
  if (name.startsWith('Immunology')) return 'Immunology';
  if (name.startsWith('Dermatology')) return 'Dermatology';
  if (name.startsWith('Renal')) return 'Renal/Electrolytes';
  if (name.startsWith('Nutrition')) return 'Nutrition/Vitamins';
  if (name.startsWith('Anaesthesia')) return 'Anaesthesia';
  if (name.startsWith('Ophthalmology')) return 'Ophthalmology';
  if (name.startsWith('Toxicology')) return 'Toxicology/Antidotes';
  return '';
}
